const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  r.scheme = m[1] ?? null
  r.authority = m[2] ?? null
  r.path = m[3]
  r.query = m[4] ?? null
  r.fragment = m[5] ?? null
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1 || 0)
  let host = hp
  let port = null
  if (colon >= 0) {
    host = hp.slice(0, colon)
    port = hp.slice(colon + 1)
  }
  return { userinfo, host, port }
}

export function removeDotSegments(path) {
  let input = path
  const out = []
  while (input.length > 0) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

