import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, UriError } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
try {
  lines.forEach((line, idx) => {
    const n = idx + 1
    const fail = (m) => { throw new UriError(`line ${n}: ${m}`) }
    try {
      if (mode === 'normalize') out.push(normalize(parse(line)))
      else {
        const sp = line.indexOf(' ')
        if (sp < 0) fail('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === null) fail('the base has no scheme')
        out.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
      }
    } catch (e) {
      if (e instanceof UriError && !e.message.startsWith('line ')) fail(e.message)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
